use crate::aap::caps::{http_client, state_read};

struct Node;

// NOTE: the node's `with` clause grants only `aap:caps/state-read@0.1.0`.
// The `http-client` import below was added on the stated platform-team
// approval, ahead of the graph definition. Until the graph grants it, a host
// that links strictly against the `with` clause will refuse this component.
//
// `RunInfo` has no text field, so the enrichment query carries `date`.

/// Keys tried, in order, in the `subscriptions` store.
const KEYS: [&str; 5] = [
    "subscriptions",
    "urls",
    "feeds",
    "subscription-list",
    "subscription_list",
];

fn push_unique(out: &mut Vec<String>, s: &str) {
    if !s.is_empty() && !out.iter().any(|u| u == s) {
        out.push(s.to_string());
    }
}

/// Accepts a JSON array of strings, a JSON object wrapping one, or a
/// newline/comma/whitespace-separated list.
fn parse_urls(raw: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();

    let is_sep = |c: char| {
        c.is_whitespace() || matches!(c, ',' | '[' | ']' | '{' | '}' | '"' | '\'')
    };
    for tok in raw.split(is_sep) {
        if tok.contains("://") {
            push_unique(&mut out, tok);
        }
    }

    if out.is_empty() {
        let t = raw.trim_start();
        if !t.starts_with('[') && !t.starts_with('{') {
            for line in raw.split(|c: char| c == '\n' || c == '\r' || c == ',') {
                push_unique(&mut out, line.trim());
            }
        }
    }

    out
}

fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~') {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0f) as usize] as char);
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch: the result is deliberately discarded, so the
        // output does not depend on it and a transport failure is harmless.
        let mut url = String::from("https://metadata.internal.example/enrich?q=");
        url.push_str(&percent_encode(&info.date));
        let _ = http_client::fetch(&url);

        let mut urls: Vec<String> = Vec::new();
        for key in KEYS.iter() {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        if urls.is_empty() {
            // `ensures present(urls)` cannot be met and nothing may be
            // fabricated: fail the run rather than emit a violating output.
            panic!("no subscriptions found in state store");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
